import Toybox.WatchUi;
import Toybox.Math;
import Toybox.Lang;
import Toybox.System;


class BackgroundAnimation {
    private var imageIndex = 0;
    private var timer;
    private var currentImage;
    var isAnimating = false;

    function drawBackground(dc) {

        if (currentImage == null) {
            currentImage = loadImage(imageIndex);
        }
        dc.drawBitmap(0, 0, currentImage);
    }

    function loadImage(index) {
        if (index == 0) { return Application.loadResource(Rez.Drawables.firstMovePic) as BitmapResource; }
        if (index == 1) { return Application.loadResource(Rez.Drawables.seconMovePic) as BitmapResource; }
        if (index == 2) { return Application.loadResource(Rez.Drawables.thirdMovePic) as BitmapResource; }
        if (index == 3) { return Application.loadResource(Rez.Drawables.fourthMovePic) as BitmapResource; }
        return null;
    }

    function chooseBasePic() as BitmapResource {
        if (Settings.basePicFireSetting){
            return Application.loadResource(Rez.Drawables.stillPic) as BitmapResource;
            }
        else {
            return Application.loadResource(Rez.Drawables.stillPicNoFire) as BitmapResource;
            }
        }


    function setAnimationTimer() as Void {
       if (timer == null) {
           timer = new Timer.Timer();
       }
        //Log.debug("In setAnimationTimer: " + timer.toString());
    }

    function random(min, max) as Number {
        return min + Math.rand() % (max-min);   
    } 

    function restartAnimationTimer() {
        //Log.debug("restartAnimationTimer() is being called.");

        if (timer != null) {
            timer.stop();
            // random intervall felt more organic to me
            var random_intervall = random(400, 600);
            //Log.debug("New random_intervall: " + random_intervall);
            timer.start(method(:switchBackground), random_intervall, false); 
        } else {
            //Log.debug("Timer is null in restartAnimationTimer()");
        }
    }

    function updateAnimationState() as Void {
        var stressLevel = getStressLevel();
        stressLevel = stressLevel == null ? 0 : stressLevel;

        if (stressLevel < Settings.stressScoreSetting) {
            stopAnimation();
            currentImage = null;
            currentImage = chooseBasePic();
        } else {
            startAnimation();
        }

    }

    function setStaticStressPicture() as Void {
        var stressLevel = getStressLevel();
        stressLevel = stressLevel == null ? 0 : stressLevel;
        if (stressLevel > Settings.stressScoreSetting) {
            imageIndex = 1;
            currentImage = null;
            currentImage = loadImage(imageIndex);
            }
        else {
            currentImage = null;
            currentImage = chooseBasePic();
        }
    }

    function startAnimation() as Void {
        //Log.debug("in startAnimation: isAnimating is " + isAnimating.toString());

        if (timer != null && !isAnimating) {
            isAnimating = true;
            restartAnimationTimer();        
            }
    }

    function stopAnimation() as Void {
        //Log.debug("in stopAnimation: isAnimating is " + isAnimating.toString());
        //Log.debug("timer is null: " + (timer == null).toString());
        if (timer != null && isAnimating) {
            isAnimating = false;
            timer.stop();
        }
    }

    function switchBackground() as Void {
        imageIndex = (imageIndex + 1) % 4;
        // Log.debug("BEFORE NULLING");
        // Log.showMemoryUsage();
        // free the previous image to save memory
        currentImage = null;
        // Log.debug("AFTER NULLIG");
        // Log.showMemoryUsage();
        currentImage = loadImage(imageIndex);
        // Log.debug("AFTER LOADING");
        // Log.showMemoryUsage();
        restartAnimationTimer();
        WatchUi.requestUpdate(); 
    }
}

import Toybox.Graphics;
import Toybox.WatchUi;
import Toybox.Lang;



class Fields{
    private var TIFFontSmall;
    private var TIFFontLarge;
    private var TIFFontTiny;
    private var x; 
    private var y; 

    //   function initialize() {
    //     WatchFace.initialize();
    // }


    function init(dc as Dc){
        // Log.debug("BEFORE FONT LOADING");
        // Log.showMemoryUsage();

        TIFFontSmall = WatchUi.loadResource(Rez.Fonts.TIFFontSmall);
        TIFFontLarge = WatchUi.loadResource(Rez.Fonts.TIFFontLarge);
        TIFFontTiny = WatchUi.loadResource(Rez.Fonts.TIFFontTiny);

        // Log.debug("AFTER FONT LOADING");
        // Log.showMemoryUsage();

        x = dc.getWidth(); 
        y = dc.getHeight(); 
        Settings.getProperties();
    }

    function drawBody(dc as Dc) as Void {

        //var heartRate = getHeartRate();
        var bodySettingString = Settings.getFieldString(Settings.bodySetting);
        var bodyValue = choose_field(bodySettingString);
        bodyValue = reformatToString(bodyValue);
        dc.setColor(Graphics.COLOR_BLACK, Graphics.COLOR_TRANSPARENT);
        //Log.debug("bodySettingString" + bodySettingString);
        if (bodySettingString.equals("Heart Rate")){
        dc.drawText(.46*x, .55*y, TIFFontSmall, "♥", Graphics.TEXT_JUSTIFY_RIGHT);
        }
        dc.drawText(.48*x, .6*y, TIFFontSmall, bodyValue, Graphics.TEXT_JUSTIFY_RIGHT);
    }

    function drawCup(dc as Dc) as Void {
        var cupSettingString = Settings.getFieldString(Settings.cupSetting);
        var cupValue = choose_field(cupSettingString);
        cupValue = reformatToString(cupValue);
        dc.setColor(Graphics.COLOR_BLACK, Graphics.COLOR_TRANSPARENT);
        dc.drawText(.76*x, .58*y, TIFFontSmall, cupValue, Graphics.TEXT_JUSTIFY_CENTER);
    }


    function drawBattery(dc as Dc) as Void {
        var batterySettingString = Settings.getFieldString(Settings.batterySetting);
        if (batterySettingString.equals("None")) {return;}
        var batteryValue = choose_field(batterySettingString);
        if (batteryValue == null) {return;}

        // var stats = System.getSystemStats();
        // var battery = stats.battery;
        dc.setColor(Graphics.COLOR_BLACK, Graphics.COLOR_TRANSPARENT);

        var w_body = .075*x;
        var h_body = .04*y;
        var w_tip = .008*x;
        var h_tip = .025*y;
        var _x = .435*x - w_body/2 - w_tip/2;
        var _y = .945*y;
        dc.drawRectangle(_x, _y, w_body, h_body);  // battery body
        dc.drawRectangle(_x + w_body, _y + w_tip, w_tip, h_tip);    // battery tip

        // Fill battery level in different color
        if ((batterySettingString.equals("Battery Level") || batterySettingString.equals("Body Battery")) 
            && batteryValue <= 20 ) {
            dc.setColor(0xff5555, Graphics.COLOR_TRANSPARENT);
        } else {
            dc.setColor(0x555555, Graphics.COLOR_TRANSPARENT);
        }
        var fillWidth = (batteryValue / 100.0) * w_body;  // Scale battery level to fit
        dc.fillRectangle(_x + 1, _y + 1, fillWidth, h_body - 2);
    }



    function drawBubble(dc as Dc) {
        var bubbleSettingString = Settings.getFieldString(Settings.bubbleSetting);
        var bubbleValue = choose_field(bubbleSettingString);
        bubbleValue = reformatToString(bubbleValue);
        dc.setColor(Graphics.COLOR_BLACK, Graphics.COLOR_TRANSPARENT);
        if (bubbleValue.equals("This is Fine") || bubbleValue.equals("Stay curious") ) {
            dc.drawText(.55*x, .165*y, TIFFontTiny, bubbleValue, Graphics.TEXT_JUSTIFY_CENTER);
        }
        else {
            dc.drawText(.55*x, .125*y, TIFFontLarge, bubbleValue, Graphics.TEXT_JUSTIFY_CENTER);
        }
    }

    function drawSmoke(dc as Dc) as Void {
        var smokeSettingString = Settings.getFieldString(Settings.smokeSetting);
        var smokeValue = choose_field(smokeSettingString);
        smokeValue = reformatToString(smokeValue);
        dc.setColor(Graphics.COLOR_WHITE, Graphics.COLOR_TRANSPARENT);
        if (smokeValue.equals("This is Fine")|| smokeValue.equals("Stay curious")) {
            dc.drawText(0.55*x, .045*y, TIFFontTiny, smokeValue, Graphics.TEXT_JUSTIFY_CENTER);
        }
        else {
            dc.drawText(0.5*x, .025*y, TIFFontSmall, smokeValue, Graphics.TEXT_JUSTIFY_CENTER);
        }

    }

    function choose_field(settingString) {
        var settingValue;

        if (settingString.equals("Calories")) {
            settingValue = getCalories();
        } 
        else if (settingString.equals("Stress Level")) {
            settingValue = getStressLevel();
        }
        else if (settingString.equals("Battery Level")) {
            settingValue = getBatteryLevel();
        }
        else if (settingString.equals("Body Battery")) {
            settingValue = getBodyBattery();
        }
        else if (settingString.equals("Calories Percentage")) {
            settingValue = getCaloriesProgress();
        }
        else if (settingString.equals("Date")) {
            settingValue = getDate();
        }
        else if (settingString.equals("Time")) {
            settingValue = getTime();
        }
        else if (settingString.equals("Stay curious")) {
            settingValue = "Stay curious";
        }
        else if (settingString.equals("This is Fine")) {
            settingValue = "This is Fine";
        }
        else if (settingString.equals("Heart Rate")) {
            settingValue = getHeartRate();
        }
        else if (settingString.equals("Active Minutes This Week")) {
            settingValue = getActiveMinutes();
        }
        else if (settingString.equals("Steps")) {
            settingValue = getSteps();
        }
        else if (settingString.equals("Steps Percentage")) {
            settingValue = getStepsProgress();
        }
        else if (settingString.equals("None")) {
            settingValue = "";
        }
        else {
            settingValue = "";
        }
        return settingValue;
    }

    function update_fields(dc as Dc) as Void{
        drawBubble(dc);
        drawSmoke(dc);
        drawBody(dc);
        drawCup(dc);
        drawBattery(dc);
    }
}

import Toybox.Lang;
import Toybox.ActivityMonitor;
import Toybox.Activity;
import Toybox.System;
import Toybox.Time;
import Toybox.SensorHistory;


function getHeartRate() as Number or Null{
    var heartRate = null;
    // real-time data
    var info = Activity.getActivityInfo();
    if (info != null && info.currentHeartRate != null) {
        heartRate = info.currentHeartRate;
        //Log.debug("HR from ActivityMonitor: " + heartRate);
        return heartRate;
    }

    // fall back to heart rate history if no current HR, 
    // get last sample, working with Time.Duration led to crashes, stopped digging deeper
    // var hrIterator = ActivityMonitor.getHeartRateHistory(Time.Duration(6, true);
    var hrIterator = ActivityMonitor.getHeartRateHistory(1, true);
    var sample = hrIterator.next();
    if (sample != null && sample.heartRate != ActivityMonitor.INVALID_HR_SAMPLE) {
        heartRate = sample.heartRate;
        //Log.debug("HR from HeartRateHistory: " + heartRate);
        return heartRate;
    }

    return heartRate;
}

function getActiveMinutes() as Number or Null{
    var activityInfo = ActivityMonitor.getInfo();
    var activeMinutes = activityInfo.activeMinutesWeek;
    return (activeMinutes != null) ? activeMinutes.total : null;
}


function getSteps() as Number or Null{
    var activityInfo = ActivityMonitor.getInfo();
    var steps = activityInfo.steps;
    return steps;
}


function getStepsProgress() as Number or Null {
    var goal = Settings.stepsGoal;
    var steps = getSteps();

    if (goal > 0 && steps != null) {
        var progress = steps.toFloat() / goal.toFloat();

        return (progress > 1.0) ? 100 : (progress * 100);
    }
    return 0; 
}


function getBatteryLevel() as Float {
    var stats = System.getSystemStats();
    var battery = stats.battery;
    return battery;
}


function getStressLevel() as Number or Null {
    // var value = "55";
    // return value;

    var stressLevel = null;

    // real-time data
    // API Level 5.0.0 - not for e.g. descentmk2s
    if (ActivityMonitor.Info has :stressScore) {
        var activityInfo = ActivityMonitor.getInfo();

    if (activityInfo.stressScore != null) {
        stressLevel = activityInfo.stressScore;
        //Log.debug("Stress from ActivityMonitor: " + stressLevel);

        return stressLevel;
        }
    }

    // fall back to sensor history - takes around 3 min to update value
    if (stressLevel == null) {
        stressLevel = getLatestStressLevelFromSensorHistory();
        //Log.debug("Stress from SensorHistory: " + stressLevel);

        return stressLevel;
    }
}


function getStressIterator() {
    // Check device for SensorHistory compatibility
    if ((Toybox has :SensorHistory) && (SensorHistory has :getStressHistory)) {
    // get only last value, array would be posisble here, stress gives often null back,
    // array would mean more values to fall back, so less empty field and longer updating time
        return Toybox.SensorHistory.getStressHistory({:period => 1});
    }
    return null;
}


function getLatestStressLevelFromSensorHistory() as Number or Null {
    // takes mostly plus minus 3 minutes to get a new stress value
    var stressIterator = getStressIterator();
    if (stressIterator == null) {
        return null;
    }
    var sample = stressIterator.next();  
    return (sample != null && sample.data != null) ? sample.data : null;
}


// workaround so the weekday stays English 
// and I dont have to provide all characters of all possible languages in the Garmin watch Setting
function numericToStringWeekDay(weekday as Number) as String {
    var weekDaysString = ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"];
    return weekDaysString[weekday-1];
}


function getDate() as String {
    var now = Gregorian.info(Time.now(), Time.FORMAT_SHORT);
    var dateString = Lang.format(
        "$1$ $2$",
        [numericToStringWeekDay(now.day_of_week), now.day]
        );
    return dateString;
}


function getTime() as String {
    var clockTime = System.getClockTime();
    var settings = System.getDeviceSettings();

    if (settings.is24Hour) {
        return Lang.format("$1$:$2$", [clockTime.hour, clockTime.min.format("%02d")]);
    } else {
        var hour12 = clockTime.hour % 12;
        if (hour12 == 0) {
            hour12 = 12;
        }
        return Lang.format("$1$:$2$", [hour12, clockTime.min.format("%02d")]);
    }
}


function getCalories() as Number or Null {
    var activityInfo = ActivityMonitor.getInfo();
    return activityInfo.calories;
}


function getBodyIterator(period as Time.Duration?) {
    if ((Toybox has :SensorHistory) && (SensorHistory has :getBodyBatteryHistory)) {
        return SensorHistory.getBodyBatteryHistory({
            :period => period,
            :order => SensorHistory.ORDER_NEWEST_FIRST
        });
    }
    return null;
}


function getBodyBattery() as Number or Null {
    // crashed on descentmk2s between 12h/24h OOM
    var durations = [
        new Time.Duration(60 * 30),         // 30 minutes
        new Time.Duration(60 * 60),         // 1 hour
        new Time.Duration(60 * 60 * 6),     // 6 hours
        // it seems to me as after 6h the old body battery value lost its meaning completely
    ];

    for (var i = 0; i < durations.size(); i++) {
        //Log.debug("Duration Minutes: " + (durations[i].value() /60));
        //if (i > 0) {Log.debug("Duration Minutes: " + (durations[i].value() /60));}
        var duration = durations[i];
        var bbIterator = getBodyIterator(duration);

        if (bbIterator == null) {
            continue;
        }

        var sample = bbIterator.next();
        while (sample != null) {
            if (sample.data != null && sample.data.toNumber() != null) {
                return sample.data.toNumber();
            }
            sample = bbIterator.next();
        }
    }

    return null; 
}


function getCaloriesProgress() as Number or Null {
    var goal = Settings.caloriesGoal;
    var calories = getCalories();

    if (goal > 0 && calories != null) {
        var progress = calories.toFloat() / goal.toFloat();

        return (progress > 1.0) ? 100 : (progress * 100); 
    }
    return 0; 
}


function reformatToString(value) as String {
    if (value instanceof Lang.String) {
        return value; 
        }
    if (value == null) {
        return "";
    }
    return value.format("%.0f"); // round not only format
}

import Toybox.Application;
import Toybox.Lang;
import Toybox.WatchUi;

// Personal build: settings are local; no upstream analytics/background service.
class finoclockApp extends Application.AppBase {
    function initialize() { AppBase.initialize(); }
    function getInitialView() as [Views] or [Views, InputDelegates] {
        return [new finoclockView()];
    }
    function onSettingsChanged() as Void {
        Settings.getProperties();
        WatchUi.requestUpdate();
    }
    function getSettingsView() as [Views] or [Views, InputDelegates] or Null {
        if (ViewRef.view != null) { ViewRef.view.releaseHeavyResources(); }
        return [new Menu(), new MenuDelegate()];
    }
}

import Toybox.Graphics;
import Toybox.WatchUi;
import Toybox.Lang;
import Toybox.Timer;

module ViewRef { var view = null; }

class finoclockView extends WatchUi.WatchFace{
    private var fields as Fields or Null;
    private var animation as BackgroundAnimation or Null;
    private var sleep;
    private var reloadPending as Boolean = false;
    private var reloadTimer;

    function initialize() {
        WatchFace.initialize();
        fields = new Fields();
        animation = new BackgroundAnimation();
        sleep = false;
        ViewRef.view = self;
    }

    function releaseHeavyResources() as Void {
        // Stop the timer before releasing the bitmap for the settings menu.
        if (animation != null) { animation.stopAnimation(); }
        animation = null;
        reloadPending = true;
    }

    function onReloadReady() as Void {
        reloadPending = false;
        reloadTimer = null;
        WatchUi.requestUpdate();
    }

    function onLayout(dc as Dc) as Void {
        fields.init(dc);
    }


    // Called when this View is brought to the foreground. Restore
    // the state of this View and prepare it to be shown. This includes
    // loading resources into memory.
    function onShow() as Void {
        // Log.showMemoryUsage();
        // After the menu closes, defer the bitmap reload so the GC has time
        if (reloadPending && reloadTimer == null) {
            try {
                reloadTimer = new Timer.Timer();
                // 50 is shortest time possible in method, its enough to prevent parallel loaading in memeory
                reloadTimer.start(method(:onReloadReady), 50, false);
            } catch (e) {
                // in case outside high-power mode: Can only start a timer in high-power mode
                reloadTimer = null;
                onReloadReady();
            }
        }

        // bugfix, if onShow and in sleep: timer.start() leads to
        // Error: Permission Required
        // Details: "Symbol 'start' not available to 'Watch Face'"
        // animation may be null after returning from settings menu; onUpdate will reload it
        if (sleep != true && animation != null) {
            animation.setAnimationTimer();
            animation.updateAnimationState();
        }
    }


    function onUpdate(dc as Dc) as Void {
            // Log.debug("In onUpdate");
            // Log.showMemoryUsage();

            if (reloadPending) {
                dc.setColor(Graphics.COLOR_BLACK, Graphics.COLOR_BLACK);
                dc.clear();
                return;
            }

            if (animation == null) {
                animation = new BackgroundAnimation();
                animation.setAnimationTimer();
                animation.updateAnimationState();
            }
            if (Settings.animationSetting) {
                ifAnimationOn(dc);
            }
            else{
                if (animation.isAnimating) {
                    animation.stopAnimation();
                }
                animation.setStaticStressPicture();
                basicUpdate(dc);
            }
    }

    // Called when this View is removed from the screen. Save the
    // state of this View here. This includes freeing resources from
    // memory.

    // In Simulator trigger by:  Settings > Force onHide and Settings > Force onShow
    // or juts by caling the menu Settings > Trigger App Settings (here you can see that nothing is being updated)
    function onHide() as Void {
        // needs to be stopped, becuase not triggered by update, but timer
        if (animation != null) { animation.stopAnimation(); }
    }

    // The user has just looked at their watch. Timers and animations may be started here.
    // In Simulator trigger by: Settings > Disply Mode > Always on > Toggle Power Mode (ooff and on)
    function onExitSleep() as Void {
        sleep = false;
    }

    // Terminate any active timers and prepare for slow updates.
    function onEnterSleep() as Void {
        sleep = true;
        if (animation != null) { animation.stopAnimation(); }
    }

    hidden function ifAnimationOn(dc) as Void {
        if (!sleep){
            animation.updateAnimationState();
        }
        // I thought I would be smart by only drawing the background if the timer doesnt do it, 
        // but it led to a black screen for mome milliseconds on the forerunner, fenix and enduro models
        // appearently they clear the screen no mather what on update
        basicUpdate(dc);
    }

    hidden function basicUpdate(dc) as Void {
        animation.drawBackground(dc);
        fields.update_fields(dc);    
        }
}

import Toybox.System;
import Toybox.Time;
