class MenuDelegate extends WatchUi.Menu2InputDelegate {

  function initialize() {
    Menu2InputDelegate.initialize();
  }

  function onSelect(item) {
    var id = item.getId();
    if (id.equals("smokeField")) {
      cycleFields(Settings.smokeSetting, item, id, null);
    }
    else if (id.equals("bubbleField")) {
      cycleFields(Settings.bubbleSetting, item, id, null);
    }
    else if (id.equals("cupField")) {
      var validKeys = [0, 1, 2, 7, 8, 9, 12]; // only none, heart rate, stress, body battery, % calories, % steps, battery level    

      cycleFields(Settings.cupSetting, item, id, validKeys);
    }
    else if (id.equals("bodyField")) {
      var validKeys = [0, 1, 2, 7, 8, 9, 12]; // only none, heart rate, stress, body battery, % calories, % steps, battery level    
      cycleFields(Settings.bodySetting, item, id, validKeys);
    }
    else if (id.equals("batteryField")) {
      var validKeys = [0, 7, 8, 9, 12]; // only none, body battery, % calories, % steps, battery level    
      cycleFields(Settings.batterySetting, item, id, validKeys);
    }
    else if (id.equals("stressThreshold")) {                                                                      
       cycleNumbers(Settings.stressScoreSetting, item, id, 10, 110);                                                                             
     }
    else if (id.equals("caloriesGoal")) {                                                                      
       cycleNumbers(Settings.caloriesGoal, item, id, 100, 10100);                                                                     
     }
      else if (id.equals("stepsGoal")) {                                                                      
       cycleNumbers(Settings.stepsGoal, item, id, 1000, 101000);                                                                     
     }
    else if (id.equals("animationSetting")) {                                                                        
       toggleAnimation(item);                                                                                         
     }      
    else if (id.equals("basePicFireSetting")) {
       toggleBasePic(item);
     }

    (Application.getApp() as finoclockApp).onSettingsChanged();
  }

//var validKeys as Null or Array<Number> = null;

  hidden function cycleFields(setting, item, fieldId, validKeys){
    if (validKeys == null) {                                                 
           validKeys = Settings.fieldsMap.keys();                               
    }     
    var currentIndex = validKeys.indexOf(setting);
    var nextIndex = (currentIndex + 1) % validKeys.size();
    // make compiler happy by giving container type
    var keys = validKeys as Array<Number>;
    setting = keys[nextIndex]; 
    item.setSubLabel(Settings.getFieldLabel(setting));
    Application.Properties.setValue(fieldId, setting);
    Settings.getProperties();
  }

  hidden function cycleNumbers(setting, item, fieldId, step, max){                                                            
     var currentValue = setting;                                                           
     var nextValue = (currentValue + step) % max;
     item.setSubLabel(nextValue.toString());                                                                   
     Application.Properties.setValue(fieldId, nextValue);                                                      
     Settings.getProperties();                                                                                     
   } 

  hidden function toggleAnimation(item){                                                                             
     Settings.animationSetting = !Settings.animationSetting;                                                                
     item.setSubLabel(Settings.animationSetting ? Rez.Strings.on : Rez.Strings.off);                                     
     Application.Properties.setValue("animationSetting", Settings.animationSetting);                                        
     Settings.getProperties();
     }    

    hidden function toggleBasePic(item){                                                                             
     Settings.basePicFireSetting = !Settings.basePicFireSetting;                                                                
     item.setSubLabel(Settings.basePicFireSetting ? Rez.Strings.on : Rez.Strings.off);                                     
     Application.Properties.setValue("basePicFireSetting", Settings.basePicFireSetting);                                        
     Settings.getProperties();
     }   
}

import Toybox.Application.Storage;
import Toybox.Lang;
import Toybox.System;

// Old devices throw "Background processes cannot modify the object store"
// Route through this module so the workaround lives in one place.

module SafeStorage {

    function getValue(key) {
        try {
            return Storage.getValue(key);
        } catch (e) {
            System.println("SafeStorage.getValue failed for key=" + key + ": " + e.getErrorMessage());
            return null;
        }
    }

    function setValue(key, value) as Boolean {
        try {
            Storage.setValue(key, value);
            return true;
        } catch (e) {
            System.println("SafeStorage.setValue failed for key=" + key + ": " + e.getErrorMessage());
            return false;
        }
    }

    function deleteValue(key) as Boolean {
        try {
            Storage.deleteValue(key);
            return true;
        } catch (e) {
            System.println("SafeStorage.deleteValue failed for key=" + key + ": " + e.getErrorMessage());
            return false;
        }
    }
}

import Toybox.Application;
import Toybox.Lang;
import Toybox.WatchUi;
import Toybox.System;


module Settings {
    var smokeSetting;
    var bubbleSetting;
    var cupSetting;
    var bodySetting;
    var stressScoreSetting;
    var caloriesGoal;
    var stepsGoal;
    var animationSetting;
    var batterySetting;
    var basePicFireSetting;


    function getOrDefault(key, defaultValue, expectedType) {
        var value = Application.Properties.getValue(key);
        return (value != null && value instanceof expectedType) ? value : defaultValue;
    }
// default values are workaround for non-reproducable (in the simulator) crash: 
// Error: Unexpected Type Error\n- **Details**: Failed invoking <symbol>
// Affected Firmware: 006-B4261-00 (14.15), 006-B3838-00 (5.10), 006-B3704-00 (19.05), 006-B3703-00 (19.05), 006-B3536-00 (8.00), 006-B4532-00 (15.32)
// in line: var fieldResource = getFieldResource(fieldId);

    function getProperties() {
        smokeSetting = getOrDefault("smokeField", 4, Lang.Number);
        bodySetting = getOrDefault("bodyField", 1, Lang.Number);
        bubbleSetting = getOrDefault("bubbleField", 5, Lang.Number);
        cupSetting = getOrDefault("cupField", 2, Lang.Number);
        batterySetting = getOrDefault("batteryField", 12,  Lang.Number);
        stressScoreSetting = getOrDefault("stressThreshold", 50, Lang.Number);
        caloriesGoal = getOrDefault("caloriesGoal", 2000, Lang.Number);
        stepsGoal = getOrDefault("stepsGoal", 10000, Lang.Number);
        animationSetting = getOrDefault("animationSetting", true, Lang.Boolean);
        basePicFireSetting = getOrDefault("basePicFireSetting", true, Lang.Boolean);
    }



    const fieldsMap = {
        0 => Rez.Strings.none,
        1 => Rez.Strings.heart,
        2 => Rez.Strings.stress,
        3 => Rez.Strings.calories,
        4 => Rez.Strings.date,
        5 => Rez.Strings.time,
        6 => Rez.Strings.thisisfine,
        7 => Rez.Strings.body,
        8 => Rez.Strings.caloriesPerc,
        9 => Rez.Strings.stepsPerc,
        10 => Rez.Strings.steps,
        11 => Rez.Strings.minutes,
        12 => Rez.Strings.battery,
        13 => Rez.Strings.staycurious,
    };

    function getFieldResource(fieldId){
        var fieldResource = fieldsMap.get(fieldId);
        return fieldResource;
    }

    function getFieldLabel(fieldId) as String{
        //Log.debug("getFieldString " + fieldId);
        var fieldResource = getFieldResource(fieldId);
        var fieldString = WatchUi.loadResource(fieldResource);
        return (fieldString != null) ? fieldString : "";
    }


    // Stable rendering keys: independent of translated menu labels.
    function getFieldString(fieldId) as String {
        var keys = ["None", "Heart Rate", "Stress Level", "Calories", "Date", "Time",
            "This is Fine", "Body Battery", "Calories Percentage", "Steps Percentage",
            "Steps", "Active Minutes This Week", "Battery Level", "Stay curious"];
        return fieldId >= 0 && fieldId < keys.size() ? keys[fieldId] : "None";
    }

    function getPropertiesAsDict() as Dictionary {
        var keys = [
            "smokeField", "bubbleField", "cupField", "bodyField",
            "batteryField", "stressThreshold", "caloriesGoal",
            "stepsGoal", "animationSetting", "basePicFireSetting"
        ];
        var result = {} as Dictionary;
        for (var i = 0; i < keys.size(); i++) {
            var value = Application.Properties.getValue(keys[i]);
            if (value != null) {
                result[keys[i]] = value;
            }
        }
        return result;
    }

}
